mapper.select:
-- 최신 묶음 순서로 고정된 pagination을 적용한다.
SELECT id, source_id, content_version_id, policy_id, discovery_status_code, set_status_code,
       manifest_hash, profile_hash, discovered_count, processed_count, is_discovery_complete,
       created_at, discovered_at, sealed_at, discovery_warning_codes_json::text AS discovery_warning_codes_json
FROM announcement_source_attachment_sets WHERE source_id = #{sourceId}
ORDER BY created_at DESC, id DESC LIMIT #{size} OFFSET #{offset}

-- source가 다르면 null을 반환한다. 빈 block 목록과 존재하지 않는 추출을 구분한다.
SELECT jsonb_array_length(blocks_json)::bigint FROM announcement_source_attachment_extractions
WHERE source_id = #{sourceId} AND id = #{extractionId}
